changeSet.sql:
ALTER TABLE tache DROP CONSTRAINT ck_tache_responsable;
ALTER TABLE tache ADD CONSTRAINT ck_tache_responsable CHECK (
    (etat = 'A_PRENDRE' AND responsable_id IS NULL AND (unite_cible IS NOT NULL OR offre_profils OR profil_requis IS NOT NULL))
    OR (etat <> 'A_PRENDRE' AND (responsable_id IS NOT NULL
        OR (etat = 'ANNULEE' AND (unite_cible IS NOT NULL OR profil_requis IS NOT NULL))
        OR (etat IN ('TERMINEE', 'ANNULEE') AND offre_profils)))
);
